// ============================================================================
// v0.60 PART 8 — THE UNVERIFIED TRIAGE, AND THE GUARD THAT MAKES IT STICK.
//
// 120 of 226 rows — 53% — are UNVERIFIED. The instrument that exists to answer "is this at
// parity?" cannot answer for the majority of the game. **But three of v0.60's finds were
// UNVERIFIED rows that fell to a single grep against a local clone**, which reframes the number:
// much of that 120 is not unverifiABLE, it is unATTEMPTED under a retrieval method that no
// longer applies.
//
// So every UNVERIFIED row is CLASSED, and the class is DERIVED FROM THE ROW rather than
// hand-assigned — 120 hand-assignments would be 120 things to maintain, and the first future
// round to add a row would forget one:
//
//   RETRIEVABLE     the counterpart column names a Kittens FILE or IDENTIFIER. Someone wrote
//                   down where to look and nobody has looked. Grep the clone.
//   RR-ORIGINAL     the counterpart column says there is none. **This is not parity debt at all
//                   — it is a category error to call it UNVERIFIED.** UNVERIFIED means "not yet
//                   looked up"; a mechanism with no counterpart cannot be looked up and must be
//                   argued EASIER or HARDER instead. Every one of these is a row somebody
//                   deferred a judgement on by mislabelling it.
//   GENUINELY OPEN  a counterpart should exist and was not found, WITH the routes tried
//                   recorded. That discipline is exactly what made `XP_PER_SECOND` findable the
//                   moment the method changed — five rounds of recorded dead ends, then one
//                   grep against a clone.
//
// THE GUARD: the generator ABORTS on an UNVERIFIED row that is GENUINELY OPEN without a recorded
// retrieval attempt. "I could not find it" is a legitimate verdict; "I did not say whether I
// looked" is not, and it is the state 48 rows were in — they carry the default note and no
// attempt at all.
function triageClass(counterpart, note) {
  const c = String(counterpart), n = String(note);
  if (/js\/|game\.js|\.js:|\bwiki\b/i.test(c)) return "RETRIEVABLE";
  if (/^none|no Kittens|RR-ORIGINAL|has no counterpart|no counterpart/i.test(c)) return "RR-ORIGINAL";
  if (/404|not present|robots|ruled out|routes|could not|no grep query|dead end/i.test(n)) return "GENUINELY OPEN";
  return "GENUINELY OPEN";
}
function hasRetrievalAttempt(note) {
  return /404|not present|robots|ruled out|routes|could not|no grep query|dead end|searched|clone/i.test(String(note));
}
